mapper.select:
SELECT COALESCE(MAX(version_no), 0) + 1
FROM edu_resource_version
WHERE resource_id = #{resourceId}

SELECT COALESCE(MAX(version_no), 0) + 1
FROM edu_question_version
WHERE question_id = #{questionId}

mapper.update:
UPDATE edu_resource_version
   SET processing_status = #{processingStatus}
 WHERE id = #{versionId}

UPDATE edu_resource_class_release
   SET ended_at = UTC_TIMESTAMP(3),
       end_kind = 'REVOKED',
       ended_by_user_id = #{userId},
       end_reason = #{reason}
 WHERE id = #{releaseId}
   AND binding_id = #{bindingId}
   AND ended_at IS NULL

UPDATE edu_question q
JOIN edu_course_class_binding b ON b.course_space_id = q.course_space_id
JOIN edu_class_teacher ct ON ct.teaching_class_id = b.teaching_class_id
   SET q.status = #{status}
 WHERE q.id = #{questionId}
   AND b.id = #{bindingId}
   AND b.ended_at IS NULL
   AND ct.user_id = #{userId}
   AND ct.valid_to IS NULL
   AND ct.can_publish = 1

