SELECT COALESCE(MAX(version_no), 0) + 1
FROM edu_submission_version
WHERE submission_id = #{submissionId}

SELECT COUNT(*) FROM edu_assignment_target
WHERE assignment_id = #{assignmentId}
  AND target_status = 'REQUIRED'
